  const [phase, setPhase] = reactExports.useState("setup");
  const [location, setLocation] = reactExports.useState(SPY_LOCATIONS[0]);
  const [playerRoles, setPlayerRoles] = reactExports.useState([]);
  const [currentPassIdx, setCurrentPassIdx] = reactExports.useState(0);
  const [isCardRevealed, setIsCardRevealed] = reactExports.useState(false);
  const [discussionSeconds, setDiscussionSeconds] = reactExports.useState(180);
  const [isTimerRunning, setIsTimerRunning] = reactExports.useState(false);
