              <div className="flex flex-col text-left">
                <span className="text-[11px] font-bold text-white leading-tight truncate max-w-[85px]">
                  {p.name}
                </span>
                <span className="text-[9px] text-[#bef264] font-mono leading-tight">
                  {p.score} Puan
                </span>
              </div>
